    while(queue.Count>0&&!seen.ContainsKey(destination)){var from=queue.Dequeue();foreach(var route in w.Campaign!.Connections.Where(c=>c.FromAreaId==from&&c.RequiredFlag==""))if(!seen.ContainsKey(route.ToAreaId)){seen[route.ToAreaId]=from;queue.Enqueue(route.ToAreaId);}}
    string next=destination;while(seen[next]!=w.CurrentTravelDestinationId)next=seen[next];Clear(w);var link=w.Campaign!.Connections.First(c=>c.FromAreaId==w.CurrentTravelDestinationId&&c.ToAreaId==next);var exit=w.Features.Single(f=>f.Id==link.ExitFeatureId);foreach(var door in w.Features.Where(f=>f.Kind=="door"))door.Used=true;var cells=w.Floors.Where(c=>c.Distance(exit.Pos)<=1.5f).OrderBy(c=>c.Distance(exit.Pos)).ToArray();int index=0;foreach(var p in w.Party)p.Pos=cells[index++];w.Reveal();check(w.TravelCampaignTo(next),"Phase 31 physical radio provenance travels to "+next);
   }
  }
