  world=Fixture(26);Clear(world);var rat=world.Campaign!.Actors.First(a=>a.Role=="Mutated Sewer Rats");world.Save(path);var bad=JsonNode.Parse(File.ReadAllText(path))!;bad["LowerMallStates"]![0]!["OuterTimers"]!["runnerAt"]=100;File.WriteAllText(path,bad.ToJsonString());bool rejected=false;try{World.Load(path);}catch(InvalidDataException){rejected=true;}check(rejected,"Phase 31 saved event ownership rejects a motel runner clock in the sewer");
